import * as T from './vendor/three.module.js';
import {islands,platforms} from './sky-engine.mjs';
export function makeWorld(){
const scene=new T.Scene();scene.background=new T.Color('#b4dae4');scene.fog=new T.FogExp2('#b4dae4',.004);
scene.add(new T.HemisphereLight(0xe6fbff,0x725346,2.4));const sun=new T.DirectionalLight(0xffe6ba,3);sun.position.set(35,65,20);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-90,right:90,top:90,bottom:-90,far:260});sun.target.position.set(0,0,-65);scene.add(sun,sun.target);sun.shadow.bias=-.001;
const mats=new Map();function mat(c,glow=false){let key=c+glow;if(!mats.has(key))mats.set(key,new T.MeshStandardMaterial({color:c,roughness:.83,flatShading:true,...(glow?{emissive:c,emissiveIntensity:.6}:{} )}));return mats.get(key);}
function mesh(geo,c,x,y,z,parent=scene,glow=false){const o=new T.Mesh(geo,mat(c,glow));o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
const box=(x,y,z,w,h,d,c,parent)=>mesh(new T.BoxGeometry(w,h,d),c,x,y,z,parent);
const ball=(x,y,z,r,c,parent)=>mesh(new T.IcosahedronGeometry(r,1),c,x,y,z,parent);
const cyl=(x,y,z,a,b,h,c,parent)=>mesh(new T.CylinderGeometry(a,b,h,10),c,x,y,z,parent);
const ring=(x,y,z,r,c,parent=scene)=>{let o=mesh(new T.TorusGeometry(r,.09,6,40),c,x,y,z,parent,true);o.rotation.x=Math.PI/2;return o;};
const plats=platforms();const platformMeshes=[];
plats.forEach((p,i)=>{const g=new T.Group();g.position.set(p.x,p.y,p.z);scene.add(g);cyl(0,-.32,0,p.r,p.r,.65,i<4?'#6eaa83':'#e8bf7f',g);cyl(0,-1.7,0,p.r*.98,p.r*.78,2.4,'#9b725f',g);mesh(new T.ConeGeometry(p.r*.8,i<4?14:6,9), '#435b60',0,i<4?-9:-5,0,g).rotation.z=Math.PI;ring(0,.06,0,p.r*.85,i<4?'#a5d7a1':'#ffdf8b',g);if(i>=4)platformMeshes.push({p,g});
if(i<4){for(let j=0;j<14;j++){let angle=j*2.4;let rad=p.r*(.7+(j%3)*.08);let v=cyl(Math.cos(angle)*rad,-3-j%4,Math.sin(angle)*rad,.15,.35,5+j%4,'#407967',g);v.rotation.z=.2;}for(let j=0;j<16;j++){const a=j*2.399;let r=p.r*.8;ball(Math.cos(a)*r,.25,Math.sin(a)*r,.45,'#e8c88c',g);}}
});
function tree(x,y,z,s=1){const g=new T.Group();g.position.set(x,y,z);g.scale.setScalar(s);scene.add(g);cyl(0,2,0,.55,1,4,'#805543',g);for(let i=0;i<5;i++){let a=i*1.26;const limb=cyl(Math.sin(a),4,Math.cos(a),.18,.3,3,'#805543',g);limb.rotation.z=Math.sin(a)*.6;limb.rotation.x=Math.cos(a)*.6;let crown=ball(Math.sin(a)*2,5.2,Math.cos(a)*2,2.1,'#3b8271',g);crown.scale.y=.55;}return g;}
[[14,0,7],[-16,0,-4],[12,0,-12],[-38,3,-59],[-20,3,-63],[36,7,-110],[21,7,-121],[-12,10,-167]].forEach(v=>tree(...v,1.2));
function stall(x,z,col){const g=new T.Group();g.position.set(x,0,z);scene.add(g);box(0,.8,0,4,1.6,2,'#bc805e',g);for(const sx of [-2,2])for(const sz of [-1,1])cyl(sx,2,sz,.09,.09,4,'#5c4a42',g);box(0,4,0,4.8,.18,3.3,col,g);for(let j=0;j<6;j++){box(-2+j*.8,4.13,0,.34,.05,3.3,'#f3d6a7',g);ball(-1.5+j*.6,1.8,0,.24,['#f3bf56','#dc7a45','#87b772'][j%3],g);}for(let j=0;j<8;j++){let f=mesh(new T.ConeGeometry(.22,.5,3),col,-2+j*.57,3.7,1.65,g);f.rotation.z=Math.PI;}}
stall(-8,4,'#39648f');stall(-10,-5,'#cc784e');stall(7,12,'#8770a8');
// Giant guardian tortoise: original fantasy sculpture, not a sacred object.
const turtle=new T.Group();turtle.position.set(0,0,-9);scene.add(turtle);let shell=ball(0,2,0,3.3,'#dfb96e',turtle);shell.scale.set(1.2,.65,1.4);for(let i=0;i<7;i++){let a=i*1.05;let plate=cyl(Math.cos(a)*1.8,3.4,Math.sin(a)*2,.75,.8,.18,'#498d83',turtle);plate.rotation.z=Math.cos(a)*.3;}ball(0,1.4,4,1,'#6eaa83',turtle);for(const x of [-2.5,2.5])for(const z of [-2,2])ball(x,.6,z,.8,'#6eaa83',turtle);ball(-.4,1.8,4.7,.12,'#16383c',turtle);ball(.4,1.8,4.7,.12,'#16383c',turtle);
// Gates frame the route.
for(const [x,y,z] of [[-8,0,-17],[-28,3,-45],[26,7,-100],[0,10,-151]]){for(const side of [-1,1]){cyl(x+side*3,y+3,z,.45,.7,6,'#c79b6d');box(x+side*3,y+5.4,z,.85,.3,.85,'#6a8d98');}box(x,y+6.2,z,7,.5,1,'#ecc77f');for(let j=0;j<5;j++){let f=mesh(new T.ConeGeometry(.35,.9,3),'#e58962',x-2+j,y+5.5,z);f.rotation.z=Math.PI;}}
const clouds=[];for(let i=0;i<35;i++){let g=new T.Group();g.position.set(Math.sin(i*7.3)*95,-9+(i%6)*1.5,25-i*7);scene.add(g);for(let j=0;j<4;j++){let m=ball(j*4,Math.sin(j)*1.5,0,4+j%2,'#ecf7ed',g);m.scale.set(1.7,.45,1);}clouds.push(g);}
// Distant scenery and falling ribbons of water.
for(let i=0;i<12;i++){const x=(i%2?1:-1)*(75+i%4*12),z=15-i*20;let m=mesh(new T.ConeGeometry(8+i%3*3,25,6),'#709e9f',x,-4,z);m.rotation.z=Math.PI;cyl(x,8,z,10,8,2,'#7ba890');}
for(const p of islands){let water=box(p.x+p.r*.8,p.y-13,p.z,1.7,25,.7,'#91e7e0');water.material=new T.MeshStandardMaterial({color:'#91e7e0',transparent:true,opacity:.65,emissive:'#439caa',emissiveIntensity:.25});}
const lanterns=[[-35,-50],[-25,-64],[-18,-51]].map(([x,z])=>{let g=new T.Group();g.position.set(x,3,z);scene.add(g);cyl(0,1.5,0,.12,.2,3,'#7e6554',g);let light=mesh(new T.OctahedronGeometry(.8),'#ffd47d',0,3.3,0,g,true);ring(0,.12,0,1.8,'#fcd681',g);return {x,z,y:3,g,light};});
const feathers=[[20,7,-101],[32,8,-102],[37,9,-111],[28,10,-119],[17,9,-117],[15,8,-108]].map(([x,y,z],i)=>{if(y>7){let p={x,y:y-1,z,r:2.2,id:'featherstep'+i};plats.push(p);cyl(x,p.y-.5,z,2.2,2.6,1,'#caaf83');}let m=mesh(new T.OctahedronGeometry(.65),'#8dffdf',x,y+1.8,z,scene,true);m.scale.set(.55,1.5,.3);return {x,y:y+1.8,z,m,id:i};});
const gems=[];for(let i=0;i<plats.length;i++){let p=plats[i];for(let j=0;j<(i<4?7:1);j++){const a=j*1.7;let x=p.x+(i<4?Math.cos(a)*10:0),z=p.z+(i<4?Math.sin(a)*10:0);let m=mesh(new T.OctahedronGeometry(.3),'#ffe195',x,p.y+1.1,z,scene,true);gems.push({m,x,z,y:p.y+1.1,id:gems.length});}}
const pads=[{x:5,y:0,z:-15},{x:24,y:7,z:-108}];pads.forEach(p=>{cyl(p.x,p.y+.06,p.z,1.6,1.6,.1,'#468f9e');ring(p.x,p.y+.2,p.z,1.2,'#8ef9ec');});
const guardian=new T.Group();guardian.position.set(0,13,-166);scene.add(guardian);ball(0,0,0,2.3,'#3c566c',guardian);for(let i=0;i<6;i++){let a=i*Math.PI/3;let m=mesh(new T.OctahedronGeometry(.8),'#a3e9e1',Math.cos(a)*3.2,0,Math.sin(a)*3.2,guardian,true);m.scale.y=1.8;}const halo=ring(0,0,0,4,'#ffd47d',guardian);const shock=ring(0,10.2,-166,1,'#f36f6e');shock.visible=false;
const beacon=mesh(new T.CylinderGeometry(.15,.8,18,8),'#ffe1a0',-28,12,-55,scene,true);beacon.material=new T.MeshBasicMaterial({color:'#ffe1a0',transparent:true,opacity:.35});
function avatar(col){const g=new T.Group();scene.add(g);let body=box(0,1.2,0,.65,.8,.4,col,g);box(0,1.53,.05,.72,.13,.5,'#ffe0a3',g);ball(0,1.99,0,.3,'#75472f',g);let hair=ball(0,2.15,-.04,.31,'#252731',g);hair.scale.y=.65;for(let i=0;i<4;i++)ball(-.18+i*.12,1.95,-.25,.085,'#252731',g);const limbs=[];for(let side of [-1,1]){let arm=new T.Group();arm.position.set(side*.42,1.5,0);g.add(arm);box(0,-.3,0,.19,.64,.22,col,arm);ball(0,-.66,0,.12,'#75472f',arm);limbs.push(arm);let leg=new T.Group();leg.position.set(side*.18,.86,0);g.add(leg);box(0,-.32,0,.23,.65,.24,'#23374e',leg);box(0,-.68,.09,.28,.17,.4,'#efcca1',leg);limbs.push(leg);}const cape=box(0,1.15,-.3,.64,.7,.07,'#ffbd69',g);cape.rotation.x=.15;return {g,limbs,body,cape};}
return {scene,plats,platformMeshes,clouds,lanterns,feathers,gems,pads,guardian,halo,shock,beacon,avatar,ring,ball,mat};}
